pragma solidity 0.8.30;

// Synthetic, local-only, intentionally non-production regression control.
contract LocalAccounting {
    address private immutable owner;
    uint256 public accounted;

    constructor() {
        require(block.chainid == 31337, "synthetic local-only fixture");
        owner = msg.sender;
    }

    function setAccounted(uint256 amount) external {
        require(msg.sender == owner, "owner only");
        accounted = amount;
    }

    function scaled(uint256 amount) external pure returns (uint256) {
        return amount * 1e18;
    }
}
"},"test/mmaudit_generated/MMAuditInvariant_Authorization.t.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;
import "../../src/LocalAccounting.sol";

interface MMAuditVm {
    function deal(address account, uint256 balance) external;
    function prank(address caller) external;
}

abstract contract MMAuditLocalInvariantTest {
    MMAuditVm internal constant vm = MMAuditVm(
        address(uint160(uint256(keccak256("hevm cheat code"))))
    );
    address[] private mmauditTargetContracts;
    event log_named_uint(string key, uint256 value);

    function targetContract(address target) internal {
        mmauditTargetContracts.push(target);
    }

    function targetContracts() public view returns (address[] memory) {
        return mmauditTargetContracts;
    }

    function bound(uint256 value, uint256 minimum, uint256 maximum)
        internal pure returns (uint256)
    {
        require(minimum <= maximum, "invalid bound");
        if (value >= minimum && value <= maximum) return value;
        uint256 span = maximum - minimum;
        if (span == type(uint256).max) return value;
        return minimum + (value % (span + 1));
    }

    function assertEq(uint256 left, uint256 right, string memory reason)
        internal pure
    {
        require(left == right, reason);
    }

    function assertGe(uint256 left, uint256 right, string memory reason)
        internal pure
    {
        require(left >= right, reason);
    }

    function assertLe(uint256 left, uint256 right, string memory reason)
        internal pure
    {
        require(left <= right, reason);
    }
}

contract MMAuditHandler_Authorization is MMAuditLocalInvariantTest {
    address internal target_LocalAccounting;

    constructor(address local_LocalAccounting) {
        target_LocalAccounting = local_LocalAccounting;
    }


    uint256 public attempts_Exercise;

    function action_Exercise() external {
        attempts_Exercise += 1;
        address actor = 0x1000000000000000000000000000000000000001;
        vm.prank(actor);
        (bool success,) = target_LocalAccounting.call{value: 0}(abi.encodeWithSignature("setAccounted(uint256)", uint256(1)));
        if (!success) return;
    }

}

contract MMAuditInvariant_Authorization is MMAuditLocalInvariantTest {
    MMAuditHandler_Authorization internal handler;
    address internal target_LocalAccounting;

    function setUp() public {
        target_LocalAccounting = address(new LocalAccounting());
        require(target_LocalAccounting.code.length > 0, "local deployment failed");
        handler = new MMAuditHandler_Authorization(target_LocalAccounting);
        targetContract(address(handler));
    }

    function invariant_Authorization() public view {
        if (handler.attempts_Exercise() == 0) return;
        (bool leftOk, bytes memory leftData) = target_LocalAccounting.staticcall(abi.encodeWithSignature("accounted()"));
        require(leftOk && leftData.length >= 32, "probe failed");
        uint256 leftValue = abi.decode(leftData, (uint256));
        assertEq(leftValue, 0, "invariant violated");
    }

}
"},"test/mmaudit_generated/MMAuditInvariant_Scaling.t.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
